import itertools

def find_all_interval(n=5):
    for perm in itertools.permutations(range(n)):
        diffs = set()
        for i in range(1, n):
            diffs.add(abs(perm[i] - perm[i-1]))
        if diffs == set(range(1, n)):
            return perm
    return None

print(find_all_interval(5))
